import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import {
  changelogHasNoReleases,
  omitUnreleasedSection,
  renderMarkdown,
  stripTicketIds,
} from "./lib/site-markdown.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "..");

const FORBIDDEN_PATTERNS = [
  /lumogis-devtools/i,
  /\.cursor\//i,
  /linear\.app/i,
  /lumogis hub/i,
];

const AUTOGEN_BANNER =
  "<!-- generated by scripts/render-lumogis-site-pages.mjs — do not edit -->\n";

function parseArgs(argv) {
  const opts = {
    capabilitiesMd: "docs/capabilities.md",
    changelogMd: "CHANGELOG.md",
    shell: "docs/private/design/site/_partials/page-shell.html",
    siteOut: null,
    assetRoot: "/",
    omitUnreleased: false,
    stripTicketIdsFlag: false,
    dryRun: false,
  };

  for (let i = 2; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === "--capabilities-md" && argv[i + 1]) {
      opts.capabilitiesMd = argv[++i];
    } else if (arg === "--changelog-md" && argv[i + 1]) {
      opts.changelogMd = argv[++i];
    } else if (arg === "--shell" && argv[i + 1]) {
      opts.shell = argv[++i];
    } else if (arg === "--site-out" && argv[i + 1]) {
      opts.siteOut = argv[++i];
    } else if (arg === "--asset-root" && argv[i + 1]) {
      opts.assetRoot = argv[++i];
    } else if (arg === "--omit-unreleased") {
      opts.omitUnreleased = true;
    } else if (arg === "--strip-ticket-ids") {
      opts.stripTicketIdsFlag = true;
    } else if (arg === "--dry-run") {
      opts.dryRun = true;
    } else if (arg === "--help" || arg === "-h") {
      printHelp();
      process.exit(0);
    } else {
      console.error(`Unknown argument: ${arg}`);
      process.exit(1);
    }
  }
  return opts;
}

function printHelp() {
  console.log(`Usage: node scripts/render-lumogis-site-pages.mjs --site-out <dir> [options]

Options:
  --capabilities-md <path>   Default: docs/capabilities.md
  --changelog-md <path>      Default: CHANGELOG.md
  --shell <path>             Default: docs/private/design/site/_partials/page-shell.html
  --site-out <dir>           Output lumogis-site public root (required unless LUMOGIS_SITE_ROOT / sibling)
  --asset-root <path>        Default: /
  --omit-unreleased          Drop ## [Unreleased] from CHANGELOG
  --strip-ticket-ids         Remove LUM-### tokens from source
  --dry-run                  Print output paths only
`);
}

function resolveSiteOut(cliSiteOut) {
  if (cliSiteOut) {
    return path.resolve(cliSiteOut);
  }
  if (process.env.LUMOGIS_SITE_ROOT) {
    return path.resolve(process.env.LUMOGIS_SITE_ROOT);
  }
  const sibling = path.resolve(REPO_ROOT, "../lumogis-site/public");
  if (
    !process.env.LUMOGIS_RENDER_DISABLE_SIBLING
    && fs.existsSync(sibling)
    && fs.statSync(sibling).isDirectory()
  ) {
    return sibling;
  }
  console.error(
    "Missing output directory: pass --site-out or set LUMOGIS_SITE_ROOT (or place lumogis-site beside lumogis-app).",
  );
  process.exit(1);
}

function readRequired(filePath) {
  const abs = path.isAbsolute(filePath)
    ? filePath
    : path.resolve(REPO_ROOT, filePath);
  if (!fs.existsSync(abs)) {
    console.error(`Missing source file: ${filePath}`);
    process.exit(1);
  }
  return { abs, content: fs.readFileSync(abs, "utf8"), mtime: fs.statSync(abs).mtime };
}

function sanitizeMarketingSource(markdown, { stripTicketIds: stripIds }) {
  let text = markdown;
  if (stripIds) {
    text = stripTicketIds(text);
  }

  text = text.replace(
    /\[([^\]]+)\]\((docs\/private\/[^)]+)\)/gi,
    "$1",
  );

  if (/docs\/private\//i.test(text)) {
    console.error("Source contains docs/private/ reference");
    process.exit(1);
  }

  const kept = [];
  let dropped = 0;
  for (const line of text.split("\n")) {
    const trimmed = line.trim();
    const isHeading = /^#{1,3}\s/.test(trimmed);
    if (!isHeading && FORBIDDEN_PATTERNS.some((re) => re.test(line))) {
      dropped += 1;
      continue;
    }
    kept.push(line);
  }
  if (dropped > 0) {
    console.error(`sanitize: dropped ${dropped} line(s) with forbidden marketing content`);
  }
  return kept.join("\n");
}

function scanForbiddenHtml(html) {
  for (const re of FORBIDDEN_PATTERNS) {
    const match = html.match(re);
    if (match) {
      console.error(`Forbidden marketing substring in output: ${match[0]}`);
      process.exit(1);
    }
  }
  if (/href="[^"]*docs\/private\//i.test(html)) {
    console.error("Forbidden docs/private/ link in output HTML");
    process.exit(1);
  }
}

function fillShell(shell, vars) {
  return shell
    .replaceAll("{{TITLE}}", vars.title)
    .replaceAll("{{DESCRIPTION}}", vars.description)
    .replaceAll("{{EYEBROW}}", vars.eyebrow)
    .replaceAll("{{BODY}}", vars.body)
    .replaceAll("{{UPDATED_ISO}}", vars.updatedIso);
}

function formatUpdatedIso(dates) {
  const max = dates.reduce((a, b) => (a > b ? a : b));
  return max.toISOString().slice(0, 10);
}

function writePage(siteOut, subdir, html, dryRun) {
  const dir = path.join(siteOut, subdir);
  const file = path.join(dir, "index.html");
  if (dryRun) {
    console.log(file);
    return;
  }
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(file, html, "utf8");
  console.log(`wrote ${file}`);
}

function buildCapabilitiesPage(shellPath, capabilitiesPath, opts) {
  const cap = readRequired(capabilitiesPath);
  const shell = readRequired(shellPath).content;
  const sanitized = sanitizeMarketingSource(cap.content, {
    stripTicketIds: opts.stripTicketIdsFlag,
  });
  let body = renderMarkdown(sanitized, {
    stripTicketIds: opts.stripTicketIdsFlag,
  });
  scanForbiddenHtml(body);

  const html = AUTOGEN_BANNER
    + fillShell(shell, {
      title: "Capabilities — Lumogis",
      description:
        "What Lumogis does today: self-hosted household AI with local search, chat, capture, and policy-gated actions.",
      eyebrow: "Product",
      body: `<article class="prose">\n${body}\n</article>`,
      updatedIso: formatUpdatedIso([cap.mtime]),
    });
  scanForbiddenHtml(html);
  return { html, mtime: cap.mtime };
}

function buildChangelogPage(shellPath, changelogPath, opts) {
  const log = readRequired(changelogPath);
  const shell = readRequired(shellPath).content;
  let source = log.content;
  if (opts.omitUnreleased) {
    source = omitUnreleasedSection(source);
  }
  const sanitized = sanitizeMarketingSource(source, {
    stripTicketIds: opts.stripTicketIdsFlag,
  });
  let body = renderMarkdown(sanitized, {
    stripTicketIds: opts.stripTicketIdsFlag,
  });
  if (changelogHasNoReleases(sanitized)) {
    body += "\n<p>No releases published yet.</p>";
  }
  scanForbiddenHtml(body);

  const html = AUTOGEN_BANNER
    + fillShell(shell, {
      title: "Changelog — Lumogis",
      description:
        "Release history for Lumogis — self-hosted household AI. Keep a Changelog format.",
      eyebrow: "Release notes",
      body: `<article class="prose">\n${body}\n</article>`,
      updatedIso: formatUpdatedIso([log.mtime]),
    });
  scanForbiddenHtml(html);
  return { html, mtime: log.mtime };
}

function main() {
  const opts = parseArgs(process.argv);
  const siteOut = resolveSiteOut(opts.siteOut);

  const capPage = buildCapabilitiesPage(opts.shell, opts.capabilitiesMd, opts);
  const logPage = buildChangelogPage(opts.shell, opts.changelogMd, opts);

  writePage(siteOut, "capabilities", capPage.html, opts.dryRun);
  writePage(siteOut, "changelog", logPage.html, opts.dryRun);
}

main();
